/// One 10a theme: its 13 colour tokens and whether it is a dark theme.
/// Views take a KTheme and read its tokens; switching themes changes colours, never layout.
public struct KTheme: Equatable, Sendable {
  /// The key themes.json and the JavaScript side use, e.g. "midnight".
  public let key: String
  /// The name shown on the Settings swatch, e.g. "Midnight".
  public let name: String
  /// True for a dark theme (Midnight). A Host showing it should use the dark color scheme.
  public let isDark: Bool
  /// Page background; also the text colour on anything filled with ink or ind.
  public let bg: Color
  /// Card face (every InkCard), the tab bar and other surfaces that sit on the page.
  public let sf: Color
  /// Main text, and the fill of solid secondary buttons.
  public let ink: Color
  /// Every outline and every hard shadow. Not the same as ink in Midnight.
  public let ln: Color
  /// Secondary text.
  public let sub: Color
  /// Small mono labels, times, placeholders.
  public let mute: Color
  /// Chevrons, disabled text, future dates.
  public let faint: Color
  /// Grouped-list (SoftGroup) background. The same as sf in Midnight.
  public let soft: Color
  /// Stat cells, progress tracks, avatar circles.
  public let soft2: Color
  /// 1pt dividers between rows.
  public let line: Color
  /// Pale selected fill: the tab lens, chips that are on.
  public let lav: Color
  /// The WRITE A LETTER composer card (used once in the mock).
  public let lav2: Color
  /// Indigo: the selected state and the main action.
  public let ind: Color

